-- Las cinco primeras solicitudes son casos fijos que usa el laboratorio de consultas:
--   1 finalizada y calificada · 2 pendiente (se acepta en la consulta U1)
--   3 aceptada · 4 pendiente (se cancela en la consulta D1) · 5 pendiente


-- Fechas de registro realistas: cada persona se registró entre 5 y 44 días antes
-- de su primera solicitud (o antes del 15 de junio si no tiene). hashtext da un
-- desfase fijo por RUT, así el resultado es el mismo en cada carga.
UPDATE cliente c
SET fecha_registro = COALESCE((SELECT MIN(s.fecha_solicitud) FROM solicitud s WHERE s.rut_cliente = c.rut_cliente),
                              TIMESTAMPTZ '2026-06-15 10:00:00-04')
                     - (ABS(hashtext(c.rut_cliente)) % 40 + 5) * INTERVAL '1 day';

UPDATE maestro m
SET fecha_registro = COALESCE((SELECT MIN(s.fecha_solicitud) FROM solicitud s WHERE s.rut_maestro = m.rut_maestro),
                              TIMESTAMPTZ '2026-06-15 10:00:00-04')
                     - (ABS(hashtext(m.rut_maestro)) % 40 + 5) * INTERVAL '1 day';
